mapper.select:
SELECT DISTINCT A.RECRUITMENT_NO AS RECRUITMENT_NO, REGEXP_SUBSTR( SUBSTR(I.BUSINESS_ADDRESS, INSTR(I.BUSINESS_ADDRESS, '^^^') + 3, INSTR(I.BUSINESS_ADDRESS || '^^^', '^^^', INSTR(I.BUSINESS_ADDRESS, '^^^') + 3) - INSTR(I.BUSINESS_ADDRESS, '^^^') - 3), '[^ ]+ [^ ]+', 1, 1 ) AS BUSINESS_ADDRESS, I.BUSINESS_NAME AS BUSINESS_NAME, A.RECRUITMENT_TITLE AS RECRUITMENT_TITLE, A.RECRUITMENT_CONTENT AS RECRUITMENT_CONTENT, A.RECRUITMENT_DEADLINE AS RECRUITMENT_DEADLINE, A.JOBTYPE_NO AS JOBTYPE_NO, A.NUM_OF_RECRUITMENT_NAME AS NUM_OF_RECRUITMENT_NAME, A.SALARY_NO AS SALARY_NO, J.SALARY_NAME AS SALARY_NAME, K.TIME_NAME AS TIME_NAME, A.GRADE_NO AS GRADE_NO, A.PERIOD_NO AS PERIOD_NO, A.DAYS_NO AS DAYS_NO, A.TIME_NO AS TIME_NO, A.EMPLOYER_NO AS EMPLOYER_NO, A.SALARY_MOUNT AS SALARY_MOUNT, A.WRITE_DATE AS WRITE_DATE, A.UPDATE_DATE AS UPDATE_DATE, A.RECRUITMENT_DEL_FL AS RECRUITMENT_DEL_FL, A.MEMBER_NO AS MEMBER_NO, A.RECRUIT_COMPLETE_FL AS RECRUIT_COMPLETE_FL, A.RECRUITMENT_PROFILE AS RECRUITMENT_PROFILE, A.WORKCOND_ADDRESS_TYPE_NO ASWORKCOND_ADDRESS_TYPE_NO FROM RECRUITMENT A JOIN EMPLOYER I ON A.EMPLOYER_NO = I.EMPLOYER_NO JOIN SALARY J ON A.SALARY_NO = J.SALARY_NO JOIN WORKCOND_TIME K ON A.TIME_NO = K.TIME_NO WHERE A.RECRUITMENT_DEL_FL = 'N'
AND A.WORKCOND_ADDRESS_TYPE_NO IN ( SELECT B.WORKCOND_ADDRESS_TYPE_NO FROM WORKCOND_ADDRESS_TYPE B WHERE -- 1) 아래 조건들이 모두 OR로 묶여야 함 1=0
OR (
B.WORKCOND_ADDRESS_TYPE_NO LIKE #{item}
)
OR (
B.WORKCOND_ADDRESS_TYPE_INFO = #{item}
)
)
AND A.EMPLOYER_NO IN ( SELECT DISTINCT C.EMPLOYER_NO FROM EMPLOYER_WORKTYPE D JOIN BUSINESS_WORKTYPE C ON C.WORKTYPE_NO = D.WORKTYPE_NO WHERE -- 1) 아래 조건들이 모두 OR로 묶여야 함 1=0
OR (
D.WORKTYPE_NO LIKE #{item}
)
OR (
D.WORKTYPE_CATEGORY = #{item}
)
)
AND A.PERIOD_NO IN ( SELECT B.PERIOD_NO FROM WORKCOND_PERIOD B WHERE
B.PERIOD_NAME LIKE #{item}
)
AND A.DAYS_NO IN ( SELECT B.DAYS_NO FROM WORKCOND_DAYS B WHERE
B.DAYS_NAME LIKE #{item}
)
AND A.TIME_NO IN ( SELECT B.TIME_NO FROM WORKCOND_TIME B WHERE
B.TIME_NAME LIKE #{item}
)
AND A.JOBTYPE_NO IN ( SELECT B.JOBTYPE_NO FROM JOBTYPE B WHERE
B.JOBTYPE_NAME LIKE #{item}
)
AND A.GRADE_NO IN ( SELECT B.GRADE_NO FROM GRADE B WHERE
B.GRADE_NAME LIKE #{item}
)
AND A.RECRUITMENT_NO IN ( SELECT DISTINCT B.RECRUITMENT_NO FROM RECRUITMENT_SUPPORT B JOIN SUPPORT C ON B.SUPPORT_NO = C.SUPPORT_NO WHERE
C.SUPPORT_CATEGORY LIKE #{item}
)
AND A.RECRUITMENT_NO IN ( SELECT DISTINCT B.RECRUITMENT_NO FROM RECRUITMENT_PREFERRED B JOIN PREFERRED C ON B.PREFERRED_NO = C.PREFERRED_NO WHERE
C.PREFERRED_CATEGORY LIKE #{item}
)
AND A.SALARY_NO IN ( SELECT B.SALARY_NO FROM SALARY B WHERE
B.SALARY_NAME LIKE #{item}
)
AND A.SALARY_NO = #{category52.salaryNo} AND A.SALARY_MOUNT >= #{category52.salaryMount}
ORDER BY A.WRITE_DATE DESC
